import{_ as a,o,c as t,a2 as i}from"./chunks/framework.DaAAbehN.js";const p=JSON.parse('{"title":"FAQ - Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix/faq.md","filePath":"en/appendix/faq.md"}'),n={name:"en/appendix/faq.md"};function r(s,e,d,l,h,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq-frequently-asked-questions" tabindex="-1">FAQ - Frequently Asked Questions <a class="header-anchor" href="#faq-frequently-asked-questions" aria-label="Permalink to &quot;FAQ - Frequently Asked Questions&quot;">​</a></h1><hr><h2 id="installation-login" tabindex="-1">Installation &amp; Login <a class="header-anchor" href="#installation-login" aria-label="Permalink to &quot;Installation &amp; Login&quot;">​</a></h2><h3 id="q1-where-can-i-download-the-codex-desktop-app" tabindex="-1">Q1: Where can I download the Codex desktop app? <a class="header-anchor" href="#q1-where-can-i-download-the-codex-desktop-app" aria-label="Permalink to &quot;Q1: Where can I download the Codex desktop app?&quot;">​</a></h3><p>A: After logging into the ChatGPT website (chatgpt.com), find the &quot;Codex&quot; entry in the left sidebar menu to download. You can also use the Code Interpreter feature directly in the ChatGPT web version.</p><h3 id="q2-can-i-use-codex-with-a-free-account" tabindex="-1">Q2: Can I use Codex with a free account? <a class="header-anchor" href="#q2-can-i-use-codex-with-a-free-account" aria-label="Permalink to &quot;Q2: Can I use Codex with a free account?&quot;">​</a></h3><p>A: Yes, but the free version has limited quota. If you use it frequently, we recommend upgrading to Plus ($20/month) or Pro ($200/month).</p><h3 id="q3-what-should-i-do-if-i-see-account-not-activated-when-logging-in" tabindex="-1">Q3: What should I do if I see &quot;Account not activated&quot; when logging in? <a class="header-anchor" href="#q3-what-should-i-do-if-i-see-account-not-activated-when-logging-in" aria-label="Permalink to &quot;Q3: What should I do if I see &quot;Account not activated&quot; when logging in?&quot;">​</a></h3><p>A: Please check your registration email and confirm you&#39;ve completed verification. If you can&#39;t find the verification email, check your spam folder, or resend the verification email.</p><h3 id="q4-on-mac-codex-says-from-an-unidentified-developer-on-first-open" tabindex="-1">Q4: On Mac, Codex says &quot;from an unidentified developer&quot; on first open? <a class="header-anchor" href="#q4-on-mac-codex-says-from-an-unidentified-developer-on-first-open" aria-label="Permalink to &quot;Q4: On Mac, Codex says &quot;from an unidentified developer&quot; on first open?&quot;">​</a></h3><p>A: This is a macOS security mechanism. Go to &quot;System Preferences → Security &amp; Privacy&quot; and click &quot;Open Anyway&quot; on the &quot;General&quot; tab.</p><hr><h2 id="permissions-workspace" tabindex="-1">Permissions &amp; Workspace <a class="header-anchor" href="#permissions-workspace" aria-label="Permalink to &quot;Permissions &amp; Workspace&quot;">​</a></h2><h3 id="q5-what-is-a-workspace-why-do-i-need-to-set-it-up" tabindex="-1">Q5: What is a workspace? Why do I need to set it up? <a class="header-anchor" href="#q5-what-is-a-workspace-why-do-i-need-to-set-it-up" aria-label="Permalink to &quot;Q5: What is a workspace? Why do I need to set it up?&quot;">​</a></h3><p>A: A workspace is the scope where Codex operates on files. Setting a workspace helps:</p><ul><li>Protect other files on your computer from accidental modifications</li><li>Help Codex better understand your project structure</li><li>Make it easy to track and manage AI modifications</li></ul><h3 id="q6-what-are-the-differences-between-the-three-permission-modes" tabindex="-1">Q6: What are the differences between the three permission modes? <a class="header-anchor" href="#q6-what-are-the-differences-between-the-three-permission-modes" aria-label="Permalink to &quot;Q6: What are the differences between the three permission modes?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th><th>Recommendation</th></tr></thead><tbody><tr><td>Default</td><td>Codex asks for your approval before any file modification</td><td>⭐⭐⭐ Best for beginners</td></tr><tr><td>Auto-review</td><td>Codex executes automatically, you audit afterward</td><td>⭐⭐ For advanced users</td></tr><tr><td>Full access</td><td>Codex has complete control</td><td>⚠️ Not recommended</td></tr></tbody></table><h3 id="q7-how-do-i-change-the-permission-mode" tabindex="-1">Q7: How do I change the permission mode? <a class="header-anchor" href="#q7-how-do-i-change-the-permission-mode" aria-label="Permalink to &quot;Q7: How do I change the permission mode?&quot;">​</a></h3><p>A: Find &quot;Permissions Management&quot; or &quot;Security Settings&quot; in Codex&#39;s settings interface and select your preferred mode.</p><hr><h2 id="usage-issues" tabindex="-1">Usage Issues <a class="header-anchor" href="#usage-issues" aria-label="Permalink to &quot;Usage Issues&quot;">​</a></h2><h3 id="q8-what-if-the-code-content-codex-generates-is-incorrect" tabindex="-1">Q8: What if the code/content Codex generates is incorrect? <a class="header-anchor" href="#q8-what-if-the-code-content-codex-generates-is-incorrect" aria-label="Permalink to &quot;Q8: What if the code/content Codex generates is incorrect?&quot;">​</a></h3><p>A: Don&#39;t worry, this is normal. You can:</p><ol><li>Tell Codex what&#39;s wrong and ask it to fix it</li><li>Provide more detailed background information</li><li>Break the big task into small steps and complete them one by one</li></ol><h3 id="q9-can-codex-operate-all-files-on-my-computer" tabindex="-1">Q9: Can Codex operate all files on my computer? <a class="header-anchor" href="#q9-can-codex-operate-all-files-on-my-computer" aria-label="Permalink to &quot;Q9: Can Codex operate all files on my computer?&quot;">​</a></h3><p>A: No. Codex can only operate on files within its authorized workspace. This is a security-by-design feature.</p><h3 id="q10-does-codex-save-my-data" tabindex="-1">Q10: Does Codex save my data? <a class="header-anchor" href="#q10-does-codex-save-my-data" aria-label="Permalink to &quot;Q10: Does Codex save my data?&quot;">​</a></h3><p>A: Codex usage records are stored in your ChatGPT account. It does not upload your private files to external servers. You can manage data retention options in ChatGPT settings.</p><h3 id="q11-does-codex-support-chinese-instructions" tabindex="-1">Q11: Does Codex support Chinese instructions? <a class="header-anchor" href="#q11-does-codex-support-chinese-instructions" aria-label="Permalink to &quot;Q11: Does Codex support Chinese instructions?&quot;">​</a></h3><p>A: Yes. Codex understands multiple languages, including Chinese and English. You can command it in whichever language you&#39;re most comfortable with.</p><hr><h2 id="quota-billing" tabindex="-1">Quota &amp; Billing <a class="header-anchor" href="#quota-billing" aria-label="Permalink to &quot;Quota &amp; Billing&quot;">​</a></h2><h3 id="q12-does-using-codex-consume-quota" tabindex="-1">Q12: Does using Codex consume quota? <a class="header-anchor" href="#q12-does-using-codex-consume-quota" aria-label="Permalink to &quot;Q12: Does using Codex consume quota?&quot;">​</a></h3><p>A: Yes. Each conversation consumes a certain amount of ChatGPT quota. Plus users have ample quota per month, and Pro users have even more.</p><h3 id="q13-what-should-i-do-when-my-quota-runs-out" tabindex="-1">Q13: What should I do when my quota runs out? <a class="header-anchor" href="#q13-what-should-i-do-when-my-quota-runs-out" aria-label="Permalink to &quot;Q13: What should I do when my quota runs out?&quot;">​</a></h3><p>A:</p><ul><li>Wait for the monthly reset (billed monthly)</li><li>Upgrade to a higher plan</li><li>Use the free version (limited quota)</li></ul><h3 id="q14-how-do-i-check-my-remaining-quota" tabindex="-1">Q14: How do I check my remaining quota? <a class="header-anchor" href="#q14-how-do-i-check-my-remaining-quota" aria-label="Permalink to &quot;Q14: How do I check my remaining quota?&quot;">​</a></h3><p>A: You can see your plan type and remaining quota in ChatGPT settings.</p><hr><h2 id="security-privacy" tabindex="-1">Security &amp; Privacy <a class="header-anchor" href="#security-privacy" aria-label="Permalink to &quot;Security &amp; Privacy&quot;">​</a></h2><h3 id="q15-is-it-safe-to-enter-sensitive-information-in-codex" tabindex="-1">Q15: Is it safe to enter sensitive information in Codex? <a class="header-anchor" href="#q15-is-it-safe-to-enter-sensitive-information-in-codex" aria-label="Permalink to &quot;Q15: Is it safe to enter sensitive information in Codex?&quot;">​</a></h3><p>A: <strong>Not recommended.</strong> Never enter passwords, bank card numbers, ID card numbers, or other sensitive information in Codex. While Codex is secure, this information should never appear in any AI conversation.</p><h3 id="q16-can-codex-leak-my-file-contents" tabindex="-1">Q16: Can Codex leak my file contents? <a class="header-anchor" href="#q16-can-codex-leak-my-file-contents" aria-label="Permalink to &quot;Q16: Can Codex leak my file contents?&quot;">​</a></h3><p>A: No. Codex processes your file contents to complete tasks and will not share them with third parties. Your data is protected by OpenAI&#39;s privacy policy.</p><h3 id="q17-how-do-i-ensure-codex-won-t-accidentally-delete-important-files" tabindex="-1">Q17: How do I ensure Codex won&#39;t accidentally delete important files? <a class="header-anchor" href="#q17-how-do-i-ensure-codex-won-t-accidentally-delete-important-files" aria-label="Permalink to &quot;Q17: How do I ensure Codex won&#39;t accidentally delete important files?&quot;">​</a></h3><p>A:</p><ol><li>Use &quot;Default Permission&quot; mode so every operation requires your confirmation</li><li>Back up important files before letting Codex operate on them</li><li>Limit the scope of Codex&#39;s workspace</li></ol><hr><h2 id="technical-support" tabindex="-1">Technical Support <a class="header-anchor" href="#technical-support" aria-label="Permalink to &quot;Technical Support&quot;">​</a></h2><h3 id="q18-what-should-i-do-if-codex-runs-slowly" tabindex="-1">Q18: What should I do if Codex runs slowly? <a class="header-anchor" href="#q18-what-should-i-do-if-codex-runs-slowly" aria-label="Permalink to &quot;Q18: What should I do if Codex runs slowly?&quot;">​</a></h3><p>A: Possible causes and solutions:</p><ul><li>Unstable network connection → Check your network</li><li>Task is too complex → Break it into smaller tasks</li><li>Server is busy → Try again later</li></ul><h3 id="q19-codex-can-t-access-certain-folders" tabindex="-1">Q19: Codex can&#39;t access certain folders? <a class="header-anchor" href="#q19-codex-can-t-access-certain-folders" aria-label="Permalink to &quot;Q19: Codex can&#39;t access certain folders?&quot;">​</a></h3><p>A: Check whether the workspace settings are correct and whether the folder has read permissions. macOS users may need to allow Codex in Full Disk Access.</p><h3 id="q20-how-do-i-get-help" tabindex="-1">Q20: How do I get help? <a class="header-anchor" href="#q20-how-do-i-get-help" aria-label="Permalink to &quot;Q20: How do I get help?&quot;">​</a></h3><p>A:</p><ul><li>OpenAI Official Documentation: <a href="https://help.openai.com" target="_blank" rel="noreferrer">https://help.openai.com</a></li><li>Community Forum: <a href="https://community.openai.com" target="_blank" rel="noreferrer">https://community.openai.com</a></li><li><a href="./prep-checklist.html">Pre-course Checklist</a> in this course&#39;s appendix</li></ul>',59)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
